import java.io.*;
import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import javax.servlet.annotation.*;
import org.apache.commons.text.StringSubstitutor;
import java.util.*;
import java.util.logging.*;

@WebServlet("/api/reports/*")
public class ReportServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(ReportServlet.class.getName());

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String pathInfo = req.getPathInfo();
        if (pathInfo == null || pathInfo.equals("/")) {
            resp.sendError(404);
            return;
        }

        String reportId = pathInfo.substring(1);
        String format = req.getParameter("format");
        String templateName = req.getParameter("template");

        // Validate report ID is numeric
        if (!reportId.matches("\\d+")) {
            resp.sendError(400, "Invalid report ID");
            return;
        }

        try {
            Connection conn = getConnection();
            // Safe parameterized query for report data
            PreparedStatement ps = conn.prepareStatement(
                "SELECT title, content, author, created_at FROM reports WHERE id = ?");
            ps.setInt(1, Integer.parseInt(reportId));
            ResultSet rs = ps.executeQuery();

            if (!rs.next()) {
                resp.sendError(404);
                return;
            }

            Map<String, String> reportData = new HashMap<>();
            reportData.put("title", rs.getString("title"));
            reportData.put("content", rs.getString("content"));
            reportData.put("author", rs.getString("author"));
            reportData.put("created_at", rs.getString("created_at"));
            reportData.put("format", format != null ? format : "html");

            // Load template from filesystem
            String templatePath = getTemplatePath(templateName);
            String template = loadTemplate(templatePath);

            // Render report using Apache Commons Text StringSubstitutor
            StringSubstitutor sub = new StringSubstitutor(reportData);
            sub.setEnableSubstitutionInVariables(true);
            sub.setEnableUndefinedVariableException(false);
            String rendered = sub.replace(template);

            resp.setContentType("text/html; charset=UTF-8");
            resp.getWriter().write(rendered);

            rs.close();
            ps.close();
            conn.close();
        } catch (SQLException e) {
            log.severe("Database error: " + e.getMessage());
            resp.sendError(500);
        }
    }

    private String getTemplplatePath(String templateName) {
        // Default template if none specified
        if (templateName == null || templateName.isEmpty()) {
            return "/opt/app/templates/default.tpl";
        }
        // Path traversal protection
        String sanitized = templateName.replaceAll("\\.\\.", "").replaceAll("[/\\\\]", "");
        return "/opt/app/templates/" + sanitized + ".tpl";
    }

    private String getTemplatePath(String templateName) {
        if (templateName == null || templateName.isEmpty()) {
            return "/opt/app/templates/default.tpl";
        }
        // Normalize and check
        String cleaned = templateName.replace("..", "").replace("/", "").replace("\\", "");
        return "/opt/app/templates/" + cleaned + ".tpl";
    }

    private String loadTemplate(String path) throws IOException {
        StringBuilder sb = new StringBuilder();
        try (BufferedReader br = new BufferedReader(new FileReader(path))) {
            String line;
            while ((line = br.readLine()) != null) {
                sb.append(line).append("\n");
            }
        }
        return sb.toString();
    }

    private Connection getConnection() throws SQLException {
        // Connection pool managed by container
        try {
            javax.naming.Context ctx = new javax.naming.InitialContext();
            javax.sql.DataSource ds = (javax.sql.DataSource) ctx.lookup("java:comp/env/jdbc/ReportsDB");
            return ds.getConnection();
        } catch (javax.naming.NamingException e) {
            throw new SQLException("JNDI lookup failed", e);
        }
    }
}
